const input = $json.body ?? $json;
const clean = (value, max = 500) => String(value ?? '').replace(/[\u0000-\u001F\u007F]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, max);
const now = new Date();
const name = clean(input.name ?? input.ansprechpartner, 120);
const company = clean(input.company ?? input.firma, 160);
const email = clean(input.email, 254).toLowerCase();
const phone = clean(input.phone ?? input.telefon, 40);
const website = clean(input.website, 300);
const interest = clean(input.interest ?? input.anliegen, 200);
const message = clean(input.message ?? input.nachricht, 3000);
let leadScore = 0;
if (website) leadScore += 10;
if (company) leadScore += 10;
if (interest.length >= 8) leadScore += 20;
if (/automat|prozess/i.test(interest + ' ' + message)) leadScore += 25;
if (/landingpage|website|webseite/i.test(interest + ' ' + message)) leadScore += 20;
if (phone) leadScore += 10;
if (message.length >= 40) leadScore += 5;
leadScore = Math.min(100, leadScore);
const priority = leadScore >= 80 ? 'A-Lead' : leadScore >= 50 ? 'B-Lead' : 'C-Lead';
const statusAllowed = ['Neu','Qualifiziert','Erstgespräch geplant','Angebot in Vorbereitung','Angebot gesendet','Follow-up nötig','Gewonnen','Verloren','Kein Interesse'];
const status = statusAllowed.includes(input.status) ? input.status : 'Neu';
const followUpDays = priority === 'A-Lead' ? 1 : priority === 'B-Lead' ? 3 : 7;
const followUpDate = input.followUpDate || new Date(now.getTime() + followUpDays * 86400000).toISOString().slice(0, 10);
const nextStep = clean(input.nextStep, 500) || (priority === 'A-Lead' ? 'Persönlich innerhalb eines Werktags kontaktieren' : priority === 'B-Lead' ? 'Bedarf prüfen und Erstgespräch anbieten' : 'Anfrage sichten und Rückmeldung vorbereiten');
const offerPotential = clean(input.offerPotential, 500) || (/automat/i.test(interest + ' ' + message) ? 'Automation & Betreuung' : /website|webseite|landingpage/i.test(interest + ' ' + message) ? 'Handwerker Landingpage' : 'Lead-System / Beratung');
const hash = [...email].reduce((value, char) => ((value << 5) - value + char.charCodeAt(0)) | 0, 0);
const leadId = clean(input.leadId, 120) || `NW-${now.toISOString().slice(0,10).replace(/-/g,'')}-${Math.abs(hash).toString(36).toUpperCase()}-${Date.now().toString(36).toUpperCase()}`;
const valid = Boolean(name && email && interest && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email));
return [{ json: { valid, error: valid ? '' : 'Name, gültige E-Mail und Anliegen sind erforderlich', leadId, createdAt: input.createdAt || now.toISOString(), company, name, email, phone, website, industry: clean(input.industry ?? input.branche, 120), interest, message, source: clean(input.source, 120) || 'Website', status, priority, leadScore, offerPotential, nextStep, followUpDate, notes: clean(input.notes ?? input.notizen, 1800), offerCreated: Boolean(input.offerCreated), offerSent: Boolean(input.offerSent), customer: Boolean(input.customer) } }];

const lead = $('CRM normalisieren & scoren').item.json;
const response = $json ?? {};
const apiFailed = Boolean(response.error || response.statusCode >= 400 || (!Array.isArray(response.results) && response.object === 'error'));
if (apiFailed) return [{ json: { ...lead, storageReady: false, success: false, report: response.message || 'Notion-Duplikatprüfung fehlgeschlagen' } }];
const matches = Array.isArray(response.results) ? response.results : [];
const duplicate = matches.length > 0;
const duplicatePageId = duplicate ? matches[0].id : '';
const rich = (text, max = 1900) => [{ type: 'text', text: { content: String(text || '').slice(0, max) } }];
const changeLog = `${duplicate ? 'Aktualisiert' : 'Erstellt'} am ${new Date().toISOString()} · Score ${lead.leadScore} · ${lead.priority}`;
const properties = {
  'Firma / Name': { title: rich(lead.company || lead.name) }, 'Lead ID': { rich_text: rich(lead.leadId) }, 'Erstellungsdatum': { date: { start: lead.createdAt } },
  'Ansprechpartner': { rich_text: rich(lead.name) }, 'E-Mail': { email: lead.email }, 'Telefon': { phone_number: lead.phone || null }, 'Website': { url: lead.website || null },
  'Branche': { rich_text: rich(lead.industry) }, 'Anliegen': { rich_text: rich(lead.interest) }, 'Nachricht': { rich_text: rich(lead.message) }, 'Lead-Quelle': { select: { name: lead.source } },
  'Status': { select: { name: lead.status } }, 'Priorität': { select: { name: lead.priority } }, 'Lead Score': { number: lead.leadScore },
  'Angebotspotenzial': { rich_text: rich(lead.offerPotential) }, 'Nächster Schritt': { rich_text: rich(lead.nextStep) }, 'Follow-up Datum': { date: { start: lead.followUpDate } },
  'Notizen': { rich_text: rich([lead.notes, changeLog].filter(Boolean).join('\n')) }, 'Angebot erstellt': { checkbox: lead.offerCreated }, 'Angebot versendet': { checkbox: lead.offerSent }, 'Kunde': { checkbox: lead.customer }
};
return [{ json: { ...lead, storageReady: true, duplicate, duplicatePageId, createBody: { parent: { database_id: 'NOVAWERK_NOTION_DATABASE_ID' }, properties }, updateBody: { properties } } }];

const lead = $('CRM Payload & Änderungslog').item.json;
const response = $json ?? {};
const success = Boolean(response.id) && !response.error;
return [{ json: { success, action: lead.duplicate ? 'updated' : 'created', duplicateSkipped: lead.duplicate, leadId: lead.leadId, notionPageId: response.id || lead.duplicatePageId || '', leadScore: lead.leadScore, priority: lead.priority, nextStep: lead.nextStep, followUpDate: lead.followUpDate, report: success ? `CRM-Datensatz ${lead.duplicate ? 'aktualisiert' : 'erstellt'}.` : (response.message || 'CRM-Speicherung fehlgeschlagen') } }];
